const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i]));
export function degrees(m){return m.atoms.map((_,i)=>m.bonds.filter(e=>e.includes(i)).length);}
export function diamondGraph(){const atoms=[],bonds=[],basis=[[0,0,0],[0,.5,.5],[.5,0,.5],[.5,.5,0],[.25,.25,.25],[.25,.75,.75],[.75,.25,.75],[.75,.75,.25]];for(let x=0;x<2;x++)for(let y=0;y<2;y++)for(let z=0;z<2;z++)for(const b of basis)atoms.push(b.map((v,i)=>(v+[x,y,z][i]-.875)*2));for(let i=0;i<atoms.length;i++)for(let j=i+1;j<atoms.length;j++)if(Math.abs(distance(atoms[i],atoms[j])-Math.sqrt(3)/2)<1e-5)bonds.push([i,j]);const m={atoms,bonds};m.focus=degrees(m).map((d,i)=>({d,i,r:Math.hypot(...atoms[i])})).filter(x=>x.d===4).sort((a,b)=>a.r-b.r)[0].i;return m;}
export function grapheneGraph(){const atoms=[],bonds=[],index=new Map(),seen=new Set();for(let c=0;c<4;c++)for(let r=0;r<3;r++){const ring=[];for(let k=0;k<6;k++){const x=1.5*c+Math.cos(k*Math.PI/3),y=Math.sqrt(3)*(r+(c%2)*.5)+Math.sin(k*Math.PI/3),key=x.toFixed(5)+','+y.toFixed(5);if(!index.has(key)){index.set(key,atoms.length);atoms.push([x-2.25,y-2.2,0]);}ring.push(index.get(key));}for(let k=0;k<6;k++){const edge=[ring[k],ring[(k+1)%6]].sort((a,b)=>a-b),key=edge.join(',');if(!seen.has(key)){seen.add(key);bonds.push(edge);}}}const m={atoms,bonds};m.focus=degrees(m).findIndex(d=>d===3);return m;}
export function c60Graph(){const phi=(1+Math.sqrt(5))/2,ico=[];for(const a of [-1,1])for(const b of [-1,1])ico.push([0,a,b*phi],[a,b*phi,0],[b*phi,0,a]);const original=[];for(let i=0;i<12;i++)for(let j=i+1;j<12;j++)if(Math.abs(distance(ico[i],ico[j])-2)<1e-5)original.push([i,j]);const atoms=[];for(const [i,j] of original){atoms.push(ico[i].map((v,k)=>(2*v+ico[j][k])/3));atoms.push(ico[j].map((v,k)=>(2*v+ico[i][k])/3));}const bonds=[];for(let i=0;i<60;i++)for(let j=i+1;j<60;j++)if(Math.abs(distance(atoms[i],atoms[j])-2/3)<1e-5)bonds.push([i,j]);return {atoms,bonds};}
export const useCases=[{material:'graphene',evidence:'electrons',brief:'An electronic component needs a one-atom-thick conducting sheet.',why:'Graphene is one sheet; delocalised electrons can carry charge.'},{material:'nanotube',evidence:'strength',brief:'A lightweight composite needs long reinforcing fibres with high strength.',why:'Strong, low-mass carbon nanotubes can reinforce a composite.'},{material:'fullerene',evidence:'hollow',brief:'Researchers need a hollow molecular cage to investigate carrying a drug.',why:'A fullerene cage offers a possible carrier shape. Release, targeting and toxicity still need testing.'}];
